<?php

namespace App\Actions\Works;

use App\Enums\RightsChangeType;
use App\Models\Work;
use App\Rules\Isrc;
use Illuminate\Support\Arr;
use Illuminate\Support\Facades\DB;

/**
 * Creates a work with its ISRCs and parties in one transaction and logs a
 * `WorkCreated` entry plus a `PartyAdded` entry per party. The TAP number is
 * generated by the model.
 */
class CreateWork
{
    public function __construct(
        private ResolveInitialEffectiveDate $resolveEffectiveDate,
        private RecordRightsHistory $recordHistory,
        private AddParty $addParty,
    ) {}

    /**
     * @param  array<string, mixed>  $data  The work fields, plus optional `isrcs` and `parties`.
     */
    public function __invoke(array $data, ?int $userId = null, ?int $csvImportId = null): Work
    {
        $parties = $data['parties'] ?? [];
        $isrcs = $data['isrcs'] ?? [];

        return DB::transaction(function () use ($data, $parties, $isrcs, $userId, $csvImportId): Work {
            $work = Work::create(Arr::except($data, ['isrcs', 'parties']));

            foreach (self::uniqueIsrcs($isrcs) as $isrc) {
                $work->isrcs()->create(['isrc' => $isrc]);
            }

            ($this->recordHistory)(
                $work,
                RightsChangeType::WorkCreated,
                ($this->resolveEffectiveDate)($work->administration_start_date),
                new: RecordRightsHistory::workSnapshot($work),
                userId: $userId,
                csvImportId: $csvImportId,
            );

            foreach ($parties as $party) {
                ($this->addParty)($work, $party, $userId, $csvImportId, validateShares: false);
            }

            return $work;
        });
    }

    /**
     * Normalise ISRCs and drop repeats.
     *
     * @param  list<string>  $isrcs
     * @return list<string>
     */
    public static function uniqueIsrcs(array $isrcs): array
    {
        return array_values(array_unique(array_map(Isrc::normalize(...), $isrcs)));
    }
}
